-- =====================================================================
-- md_std_gov_others_fill.sql
-- เพิ่ม 113 ประเทศที่มี arrival ปี 2024 ลงใน OTHERS buckets ของ STD_GOV
-- Schema: Oracle TAT (139.180.208.163:1521 SID=XE schema=TAT)
-- รันทั้งไฟล์ครั้งเดียว (มี COMMIT ในตัว + BEFORE/AFTER verify)
--
-- เป้าหมาย: nation_compare 08-09-2024 STD_GOV 72,681 → 72,955 (= ALL/STD_TAT)
--
-- โครงสร้าง STD_GOV มี 6 OTHERS regions ว่างเปล่าอยู่แล้ว:
--   NODE=30  'OTHER IN ASIA'        (parent=1, ASIA AND THE PACIFIC)
--   NODE=34  'OTHER IN OCEANIA'     (parent=1)
--   NODE=79  'OTHER IN EUROPE'      (parent=35, EUROPE)
--   NODE=90  'OTHER IN AMERICA'     (parent=ROOT)
--   NODE=103 'OTHER IN MIDDLE EAST' (parent=ROOT)
--   NODE=110 'OTHER IN AFRICA'      (parent=ROOT)
--
-- NODE_ID range: 1000-1112 (max ปัจจุบัน หลัง STD_TAT fill = 983)
-- GROUP_ID = 1 (STD_GOV)
-- =====================================================================

-- ====== BEFORE: ตรวจสถานะ OTHERS regions (ต้องเห็น 6 row, NC=0 ทุกตัว) ======
SELECT 'BEFORE - STD_GOV OTHERS regions' AS phase, NODE_ID, NAME_EN,
       (SELECT COUNT(*) FROM MD_COUNTRY_GROUP_NODE c
        WHERE c.PARENT_NODE_ID = n.NODE_ID AND c.NODE_TYPE = 'COUNTRY') AS NC
FROM MD_COUNTRY_GROUP_NODE n
WHERE n.NODE_ID IN (30, 34, 79, 90, 103, 110)
ORDER BY n.NODE_ID;

-- ====== BACKUP (optional) ======
-- CREATE TABLE MD_COUNTRY_GROUP_NODE_BAK_STDGOV_OTHERS AS SELECT * FROM MD_COUNTRY_GROUP_NODE;

-- ---------- OTHER IN ASIA (parent=30) — 2 ประเทศ ----------

-- ---------- OTHER IN OCEANIA (parent=34) — 14 ประเทศ ----------

-- ---------- OTHER IN EUROPE (parent=79) — 15 ประเทศ ----------

-- ---------- OTHER IN AMERICA (parent=90) — 31 ประเทศ ----------

-- ---------- OTHER IN MIDDLE EAST (parent=103) — 3 ประเทศ ----------

-- ---------- OTHER IN AFRICA (parent=110) — 48 ประเทศ ----------

COMMIT;

-- =====================================================================
-- AFTER: ตรวจสอบหลัง INSERT
-- =====================================================================

-- 1) นับ COUNTRY ใน 6 OTHERS bucket (ต้องได้: 2, 14, 15, 31, 3, 48)
SELECT 'AFTER - OTHERS country counts' AS phase, NODE_ID, NAME_EN,
       (SELECT COUNT(*) FROM MD_COUNTRY_GROUP_NODE c
        WHERE c.PARENT_NODE_ID = n.NODE_ID AND c.NODE_TYPE = 'COUNTRY') AS NC
FROM MD_COUNTRY_GROUP_NODE n
WHERE n.NODE_ID IN (30, 34, 79, 90, 103, 110)
ORDER BY n.NODE_ID;

-- 2) นับ country ทั้งหมดใน STD_GOV (ต้องได้ 91 + 113 = 204)
SELECT 'AFTER - STD_GOV total country count' AS phase, COUNT(DISTINCT n.COUNTRY_ID) AS CNT
FROM MD_COUNTRY_GROUP g
JOIN MD_COUNTRY_GROUP_NODE n ON n.GROUP_ID = g.GROUP_ID
WHERE g.GROUP_CODE = 'STD_GOV' AND n.NODE_TYPE = 'COUNTRY' AND n.COUNTRY_ID IS NOT NULL;

-- 3) ไม่มี duplicate COUNTRY_ID ใน STD_GOV (ต้องได้ 0 rows)
SELECT 'AFTER - STD_GOV duplicates' AS phase, n.COUNTRY_ID, COUNT(*) AS CNT
FROM MD_COUNTRY_GROUP g
JOIN MD_COUNTRY_GROUP_NODE n ON n.GROUP_ID = g.GROUP_ID
WHERE g.GROUP_CODE = 'STD_GOV' AND n.NODE_TYPE = 'COUNTRY' AND n.COUNTRY_ID IS NOT NULL
GROUP BY n.COUNTRY_ID
HAVING COUNT(*) > 1;
